#include <stdio.h>
#include <signal.h>
#include <string.h>

volatile sig_atomic_t usr1 = 0, usr2 = 0;

void on_signal(int sig) {
    if (sig == SIGUSR1) usr1++;
    else if (sig == SIGUSR2) usr2++;
}

int main(void) {
    signal(SIGUSR1, on_signal);
    signal(SIGUSR2, on_signal);

    int n;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        char cmd[16], name[16];
        scanf("%15s %15s", cmd, name);
        int sig = strcmp(name, "USR1") == 0 ? SIGUSR1 : SIGUSR2;
        sigset_t set;
        sigemptyset(&set);
        sigaddset(&set, sig);
        if (strcmp(cmd, "raise") == 0) raise(sig);
        else if (strcmp(cmd, "block") == 0) sigprocmask(SIG_BLOCK, &set, NULL);
        else sigprocmask(SIG_UNBLOCK, &set, NULL);
    }

    sigset_t waiting;
    sigpending(&waiting);
    printf("USR1 handled %d\nUSR2 handled %d\n", (int)usr1, (int)usr2);
    int p1 = sigismember(&waiting, SIGUSR1), p2 = sigismember(&waiting, SIGUSR2);
    if (!p1 && !p2) printf("pending: none\n");
    else printf("pending:%s%s\n", p1 ? " USR1" : "", p2 ? " USR2" : "");
    return 0;
}
